      "unit-bladeguard-veteran-squad",
      "unit-company-heroes",
      "unit-devastator-squad",
      "unit-sternguard-veteran-squad",
      "unit-terminator-assault-squad",
      "unit-terminator-squad",
      "unit-dreadnought",
      "unit-gladiator-reaper",
