    "title": "Support",
    "summary": "This model can be attached to the following units: ■ ASSAULT INTERCESSOR SQUAD ■ CRUSADER SQUAD ■ DEATHWATCH VETERANS ■ DECIMUS KILL TEAM ■ DESOLATION SQUAD ■ DEVASTATOR SQUAD ■ FORTIS KILL TEAM ■ HELLBLASTER SQUAD ■ INFERNUS SQUAD ■ INNER CIRCLE COMPANIONS ■ INTERCESSOR SQUAD ■ STERNGUARD VETERAN SQUAD ■ SWORD BRETHREN SQUAD ■ TACTICAL SQUAD You can attach this model to one of the above units even if one Captain, Chapter Master or Lieutenant model has already been attached to it. If you do, and that Bodyguard unit is destroyed, the Leader units attached to it become separate units, with their original Starting Strengths.",
