    "id": "dark-angels-ability-tank-commander",
    "title": "Tank Commander",
    "summary": "While this model is commanding a Vehicle model (see reverse): ■ Ranged weapons equipped by that Vehicle model have a Ballistic Skill characteristic of 2+. ■ Each time that Vehicle model is selected to shoot, you can re-roll one Wound roll when resolving those attacks. If your army includes one or more of the Vehicle models listed below, Sergeant Chronus must start the battle embarked within one of those models as if it were a Transport. Sergeant Chronus can only disembark from that Vehicle if it is destroyed. While embarked in this way, Sergeant Chronus is said to be commanding that Vehicle. ■ Hunter ■ Land Raider ■ Land Raider Crusader ■ Land Raider Redeemer ■ Predator Annihilator ■ Predator Destructor ■ Stalker ■ Vindicator ■ Whirlwind",
    "full": "While this model is commanding a Vehicle model (see reverse): ■ Ranged weapons equipped by that Vehicle model have a Ballistic Skill characteristic of 2+. ■ Each time that Vehicle model is selected to shoot, you can re-roll one Wound roll when resolving those attacks. If your army includes one or more of the Vehicle models listed below, Sergeant Chronus must start the battle embarked within one of those models as if it were a Transport. Sergeant Chronus can only disembark from that Vehicle if it is destroyed. While embarked in this way, Sergeant Chronus is said to be commanding that Vehicle. ■ Hunter ■ Land Raider ■ Land Raider Crusader ■ Land Raider Redeemer ■ Predator Annihilator ■ Predator Destructor ■ Stalker ■ Vindicator ■ Whirlwind",
    "glossary": "glossary-dark-angels-ability-tank-commander",
