    "title": "Stasis Bomb",
    "summary": "At the end of your opponent’s Fight phase, select one visible enemy unit (excluding AIRCRAFT/Lone Operative units) within 24\" of this unit. That enemy unit is slowed until the end of your opponent’s next Movement phase: ▪ While a unit is slowed, in your opponent’s Movement phase, when that unit is selected to move, unless that unit remains stationary, roll one D6: ▫ On a 1-4, that unit suffers D3 mortal wounds and that unit has -2\" M. ▫ On a 5-6, that unit suffers 2D3 mortal wounds and that unit has -3\" M.’",
    "full": "At the end of your opponent’s Fight phase, select one visible enemy unit (excluding AIRCRAFT/Lone Operative units) within 24\" of this unit. That enemy unit is slowed until the end of your opponent’s next Movement phase: ▪ While a unit is slowed, in your opponent’s Movement phase, when that unit is selected to move, unless that unit remains stationary, roll one D6: ▫ On a 1-4, that unit suffers D3 mortal wounds and that unit has -2\" M. ▫ On a 5-6, that unit suffers 2D3 mortal wounds and that unit has -3\" M.’",
    "glossary": "glossary-dark-angels-ability-stasis-bomb",
